def segmented_sieve(n):
    if n < 2:
        return []
    # Generate primes up to sqrt(n) using the standard sieve
    limit = int(n ** 0.5) + 1
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    primes = [i for i, prime in enumerate(is_prime) if prime]

    # Create a boolean array for the range [0, n]
    sieve = [True] * (n + 1)
    for p in primes:
        start = max(p * p, ((n // p) * p) - (p - 1))
        for i in range(start, n + 1, p):
            sieve[i] = False

    # Mark multiples of primes in the range [0, n]
    for i in range(2, n + 1):
        if sieve[i] and i not in primes:
            sieve[i] = False

    # Collect the primes in the range [0, n]
    primes_in_range = [i for i, prime in enumerate(sieve) if prime]
    return primes_in_range

def sum_primes_segmented(n):
    primes = segmented_sieve(n)
    return sum(primes)
